(()=>{const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg'),out={};document.body.append(svg);for(const [name,d]of [['line','M0 0L10 0'],['corner','M0 0L10 0L10 10'],['closed','M0 0L10 0L10 10Z']])for(const cap of ['butt','round','square'])for(const join of ['miter','round','bevel']){const n=document.createElementNS(ns,'path');n.setAttribute('d',d);n.setAttribute('stroke-width','4');n.setAttribute('stroke-linecap',cap);n.setAttribute('stroke-linejoin',join);svg.append(n);out[name+cap+join]=[[-1,0],[-1,1.8],[11,0],[11,1.8],[11,-1.8],[11.8,-1.8],[9,-1.8],[10,11],[0,2.1],[5,1]].map(([x,y])=>n.isPointInStroke({x,y}));n.remove()}svg.remove();return out})()
